func splitPairs(s string) [][2]string {
	var out [][2]string
	for _, it := range splitOn(s, '|') {
		for i := 0; i < len(it); i++ {
			if it[i] == ' ' {
				out = append(out, [2]string{it[:i], it[i+1:]})
				break
			}
		}
	}
	return out
}

func splitOn(s string, sep byte) []string {
	var out []string
	st := 0
	for i := 0; i < len(s); i++ {
		if s[i] == sep {
			out = append(out, s[st:i])
			st = i + 1
		}
	}
	return append(out, s[st:])
}
